def parse_max_batch(raw):
    if not raw.isdigit() or not 1 <= int(raw) <= 1000:
        raise ValueError(f"MAX_BATCH must be 1 to 1000, got {raw!r}")
    return int(raw)


for raw in ["100", "0", "50.5", " 20"]:
    try:
        print(parse_max_batch(raw))
    except ValueError:
        print("rejected", repr(raw))

